CREATE TABLE IF NOT EXISTS provinces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(30) UNIQUE, name varchar(120) NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS municipalities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), province_id uuid REFERENCES provinces(id), code varchar(30), name varchar(120) NOT NULL, kind varchar(20) NOT NULL DEFAULT 'MUNICIPALITY' CHECK (kind IN ('MUNICIPALITY','COMPONENT_CITY','INDEPENDENT_CITY','HIGHLY_URBANIZED_CITY')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(province_id,name), UNIQUE(id,province_id));
CREATE UNIQUE INDEX IF NOT EXISTS municipalities_scope_name_uq ON municipalities(name,COALESCE(province_id,'00000000-0000-0000-0000-000000000000'::uuid));
CREATE TABLE IF NOT EXISTS departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL, description varchar(500), email varchar(254), province_id uuid REFERENCES provinces(id), municipality_id uuid REFERENCES municipalities(id), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE departments ADD CONSTRAINT departments_municipality_province_fk FOREIGN KEY(municipality_id,province_id) REFERENCES municipalities(id,province_id);
CREATE UNIQUE INDEX IF NOT EXISTS departments_scope_name_uq ON departments(name,COALESCE(province_id,'00000000-0000-0000-0000-000000000000'::uuid),COALESCE(municipality_id,'00000000-0000-0000-0000-000000000000'::uuid));
CREATE TABLE IF NOT EXISTS app_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), keycloak_sub varchar(128) UNIQUE, email varchar(254) NOT NULL UNIQUE, display_name varchar(160) NOT NULL, active boolean NOT NULL DEFAULT true, last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(60) NOT NULL UNIQUE, name varchar(120) NOT NULL, description varchar(500));
INSERT INTO roles(code,name) VALUES ('SYSTEM_ADMIN','System Administrator'),('PROVINCIAL_ADMIN','Provincial Administrator'),('PROVINCIAL_DEPARTMENT_ADMIN','Provincial Department Administrator'),('MUNICIPAL_ADMIN','Municipal Administrator'),('MUNICIPAL_DEPARTMENT_ADMIN','Municipal Department Administrator'),('DEPARTMENT_STAFF','Department Staff'),('AUDITOR','Auditor') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS user_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES roles(id), province_id uuid REFERENCES provinces(id), municipality_id uuid REFERENCES municipalities(id), department_id uuid REFERENCES departments(id), created_by uuid REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(municipality_id,province_id) REFERENCES municipalities(id,province_id));
CREATE INDEX IF NOT EXISTS user_assignments_user_idx ON user_assignments(user_id);
CREATE TABLE IF NOT EXISTS invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email varchar(254) NOT NULL, display_name varchar(160) NOT NULL, token_hash varchar(128) NOT NULL UNIQUE, role_id uuid NOT NULL REFERENCES roles(id), province_id uuid REFERENCES provinces(id), municipality_id uuid REFERENCES municipalities(id), department_id uuid REFERENCES departments(id), invited_by uuid REFERENCES app_users(id), expires_at timestamptz NOT NULL, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS access_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email varchar(254) NOT NULL, display_name varchar(160) NOT NULL, requested_role_id uuid NOT NULL REFERENCES roles(id), province_id uuid REFERENCES provinces(id), municipality_id uuid REFERENCES municipalities(id), department_id uuid REFERENCES departments(id), justification text NOT NULL, status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')), reviewed_by uuid REFERENCES app_users(id), reviewed_at timestamptz, review_note text, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE invitations ADD CONSTRAINT invitations_municipality_province_fk FOREIGN KEY(municipality_id,province_id) REFERENCES municipalities(id,province_id);
ALTER TABLE access_requests ADD CONSTRAINT access_requests_municipality_province_fk FOREIGN KEY(municipality_id,province_id) REFERENCES municipalities(id,province_id);
CREATE INDEX IF NOT EXISTS access_requests_status_idx ON access_requests(status,created_at);
CREATE TABLE IF NOT EXISTS reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference varchar(32) NOT NULL UNIQUE, title varchar(140) NOT NULL, description text NOT NULL, category varchar(60) NOT NULL, priority varchar(20) NOT NULL DEFAULT 'NORMAL' CHECK(priority IN ('LOW','NORMAL','HIGH','URGENT')), status varchar(20) NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN ('SUBMITTED','ACKNOWLEDGED','IN_PROGRESS','RESOLVED','REJECTED')), reporter varchar(120), email varchar(254), latitude double precision NOT NULL, longitude double precision NOT NULL, address varchar(300), province_id uuid REFERENCES provinces(id), municipality_id uuid REFERENCES municipalities(id), department_id uuid REFERENCES departments(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE reports ADD CONSTRAINT reports_municipality_province_fk FOREIGN KEY(municipality_id,province_id) REFERENCES municipalities(id,province_id);
CREATE INDEX IF NOT EXISTS reports_status_created_idx ON reports(status,created_at DESC);
CREATE INDEX IF NOT EXISTS reports_category_created_idx ON reports(category,created_at DESC);
CREATE INDEX IF NOT EXISTS reports_location_idx ON reports(latitude,longitude);
CREATE INDEX IF NOT EXISTS reports_department_status_idx ON reports(department_id,status);
CREATE TABLE IF NOT EXISTS evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, object_key varchar(1000) NOT NULL UNIQUE, url varchar(1000) NOT NULL, file_name varchar(255) NOT NULL, mime_type varchar(120) NOT NULL, size integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS evidence_report_idx ON evidence(report_id);
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid REFERENCES reports(id) ON DELETE SET NULL, actor varchar(160) NOT NULL, action varchar(80) NOT NULL, details jsonb, ip_address varchar(64), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_report_created_idx ON audit_logs(report_id,created_at DESC);
CREATE INDEX IF NOT EXISTS audit_created_idx ON audit_logs(created_at DESC);
